import pandas as pd
def load_month(path, sheet):
    return pd.read_excel(path, sheet_name=sheet)

data={
  "2026-04": ("So_chi_tiet_ban_hang_1.xlsx","T04_2026"),
  "2026-05": ("So_chi_tiet_ban_hang_1.xlsx","T05_2026"),
  "2026-06": ("So_chi_tiet_ban_hang_2026.xlsx","T06_2026"),
}

monthly={}
for m,(p,s) in data.items():
    df=load_month(p,s)
    s2=df["Thành tiền"].str.replace(r"\s+","",regex=True)
    s2=s2.str.replace(",","",regex=True).str.replace(r"\.","",regex=0)
    df["_amt"]=pd.to_numeric(s2, errors="coerce")
    done=df[df["Trạng thái"]=="Đã hoàn thành"]
    monthly[m]=int(done["_amt"].sum())

series=dict(sorted(monthly.items()))
for m,v in series.items(): print(m,v)
apr=monthly["2026-04"]; may=monthly["2026-05"]; jun=monthly["2026-06"]
print(f"Apr={apr:,}  May={may:,}  Jun={jun:,}")
print(f"Apr->May delta={may-apr}  (growth {(may-apr)/apr*100:.2f}%)")
print(f"May->Jun delta={jun-may}  (growth {(jun-may)/may*100:.2f}%)")
print("Apr<May<Jun strictly increasing:", apr<may<jun)
